#ifndef ULMBLAS_LEVEL3_UKERNEL_OPENBLAS_SMALL_H
#define ULMBLAS_LEVEL3_UKERNEL_OPENBLAS_SMALL_H 1

//
//  The DGEMM kernels for small matrices of OpenBLAS for SKYLAKEX (AVX-512F,
//  kernel/d_small_*_skylakex.h, generated by mk/vendor_openblas_kernels.py)
//  as a plan of gemm (ulmblas/level3/gemm/select.h):
//
//      C <- beta C + alpha op(A) op(B)
//
//  without packing, with A and B column major or row major (the kernels NN,
//  NT, TN, TT) and C column major; the kernels for beta = 0 do not read C.
//  OpenBLAS's permit function decides, as in OpenBLAS, whether the kernels
//  are used (m n k <= 10^6; for A row major and B column major only for
//  m n <= 1200 and k >= 32).  Otherwise, and for other strides, types or
//  conjugation, the frame algorithm Fallback computes the product.
//
//  Available if the build has AVX-512F and AVX-512VL (ULMBLAS_OPENBLAS_SMALL
//  is then defined).
//

#include <cstddef>
#include <ulmblas/auxiliary/memorypool.h>
#include <ulmblas/level3/gemm/threads.h>

#if defined(__AVX512F__) && defined(__AVX512VL__) && defined(__x86_64__)

#define ULMBLAS_OPENBLAS_SMALL 1

#include <ulmblas/level3/ukernel/openblas/kernel/d_small_nn_b0_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_nn_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_nt_b0_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_nt_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_permit_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_tn_b0_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_tn_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_tt_b0_skylakex.h>
#include <ulmblas/level3/ukernel/openblas/kernel/d_small_tt_skylakex.h>

namespace ulmBLAS {
namespace openblas {
namespace small {

//
//  The layout of a matrix with r rows and c columns for the kernels: false
//  (column major, leading dimension incCol), true (row major, incRow), or
//  not supported (false returned).
//
template <typename IndexType>
bool
layout(IndexType r, IndexType c, IndexType incRow, IndexType incCol,
       bool &trans, compat::BLASLONG &ld)
{
    if (incRow == IndexType(1) && incCol >= (r > 1 ? r : IndexType(1))) {
	trans = false;
	ld = incCol;
	return true;
    }
    if (incCol == IndexType(1) && incRow >= (c > 1 ? c : IndexType(1))) {
	trans = true;
	ld = incRow;
	return true;
    }
    return false;
}

template <typename IndexType, typename Alpha, typename TA, typename TB,
          typename Beta, typename TC>
inline bool
run(IndexType m, IndexType n, IndexType k, const Alpha &alpha, bool conjA,
    const TA *A, IndexType incRowA, IndexType incColA, bool conjB, const TB *B,
    IndexType incRowB, IndexType incColB, const Beta &beta, TC *C,
    IndexType incRowC, IndexType incColC)
{
    return false;
}

template <typename IndexType>
inline bool
run(IndexType m, IndexType n, IndexType k, const double &alpha, bool conjA,
    const double *A, IndexType incRowA, IndexType incColA, bool conjB,
    const double *B, IndexType incRowB, IndexType incColB, const double &beta,
    double *C, IndexType incRowC, IndexType incColC)
{
    using compat::BLASLONG;

    bool transA, transB;
    BLASLONG ldA, ldB;
    if (conjA || conjB || incRowC != IndexType(1) ||
        incColC < (m > 1 ? m : IndexType(1)) ||
        !layout(m, k, incRowA, incColA, transA, ldA) ||
        !layout(k, n, incRowB, incColB, transB, ldB)) {
	return false;
    }
    if (!kernel::d_small_permit_skylakex::dgemm_small_kernel_permit(
            transA, transB, m, n, k, alpha, beta)) {
	return false;
    }
    //  the kernels take the operands as pointers to non-const (they do not
    //  write A and B)
    double *a = const_cast<double *>(A), *b = const_cast<double *>(B);
    const BLASLONG M = m, N = n, K = k, ldC = incColC;
    if (beta == 0.0) {
	if (!transA && !transB) {
	    kernel::d_small_nn_b0_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, C, ldC);
	} else if (!transA) {
	    kernel::d_small_nt_b0_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, C, ldC);
	} else if (!transB) {
	    kernel::d_small_tn_b0_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, C, ldC);
	} else {
	    kernel::d_small_tt_b0_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, C, ldC);
	}
    } else {
	if (!transA && !transB) {
	    kernel::d_small_nn_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, beta, C, ldC);
	} else if (!transA) {
	    kernel::d_small_nt_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, beta, C, ldC);
	} else if (!transB) {
	    kernel::d_small_tn_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, beta, C, ldC);
	} else {
	    kernel::d_small_tt_skylakex::dgemm_small_kernel(
	        M, N, K, a, ldA, alpha, b, ldB, beta, C, ldC);
	}
    }
    return true;
}

} // namespace small

template <typename Fallback> struct SmallGemm
{
    //  the frame for the other problems (also for the operations without
    //  a kernel for small matrices, see GemmFrameOf, gemm/plan.h)
    typedef Fallback FallbackType;

    template <typename IndexType, typename Alpha, typename TA, typename TB,
              typename Beta, typename TC>
    static void
    run(IndexType m, IndexType n, IndexType k, const Alpha &alpha, bool conjA,
        const TA *A, IndexType incRowA, IndexType incColA, bool conjB,
        const TB *B, IndexType incRowB, IndexType incColB, const Beta &beta,
        TC *C, IndexType incRowC, IndexType incColC)
    {
	//  single threaded: problems with more threads to the frame
	typedef decltype(Alpha(0) * TA(0) * TB(0)) T;
	if (GemmThreads::forProblem<T>(m, n, k) > 1 ||
	    !small::run(m, n, k, alpha, conjA, A, incRowA, incColA, conjB, B,
	                incRowB, incColB, beta, C, incRowC, incColC)) {
	    Fallback::template run<IndexType, Alpha, TA, TB, Beta, TC>(
	        m, n, k, alpha, conjA, A, incRowA, incColA, conjB, B, incRowB,
	        incColB, beta, C, incRowC, incColC);
	}
    }
};

} // namespace openblas
} // namespace ulmBLAS

#endif // __AVX512F__ && __AVX512VL__ && __x86_64__

#endif // ULMBLAS_LEVEL3_UKERNEL_OPENBLAS_SMALL_H
